M(2,"w2t1","people",2,"Semanalysis is associated with…",["Julia Kristeva","Roland Barthes","Charles Morris","Olzhas Suleimenov"],"Kristeva (b. 1941).");
F(2,"w2t1","def",2,"Signs organized into sequences that generate meaning through cultural conventions are called cultural ____.",["codes","code"],"Cultural codes.");
TF(2,"w2t1","people",3,"Charles Morris developed the ideas of Ferdinand de Saussure.",false,"False – Morris developed PEIRCE's ideas.");
S(2,"w2t1","compare",3,"Compare Saussure's and Peirce's approaches to the sign.",[["saussure"],["peirce"],["signifier","signified"],["icon","index","symbol"],["interpret","semiosis","interpretant"],["european","american","pragmatic","semiology"]],"Saussure (European structural tradition, 'semiology') saw language as a system and the sign as two parts: signifier (form) + signified (concept). Peirce (American pragmatic tradition, 'semiotics') saw meaning as a dynamic process of interpretation (semiosis) involving an interpretant, and classified signs as icon (similarity), index (direct connection) and symbol (convention).");
M(2,"w2t2","theory",1,"Barthes' three levels of meaning are…",["denotation – connotation – myth","signifier – signified – sign","icon – index – symbol","semantics – syntactics – pragmatics"],"Barthes, Mythologies.");
