M(10,"w10t1","event",2,"Which monuments were restored under Madeni Mura?",["the mausoleums of Aisha Bibi and Arystan Bab","the Khan Shatyr and Baiterek","the Eiffel Tower","the Palace of Peace"],"Aisha Bibi, Arystan Bab, Abat-Baitak…");
